$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';$root='C:\JudasValidation';$base='http://192.168.122.1:8872';$out="$root\M78ContinuationResults"
function Upload($p,$name){Invoke-WebRequest -UseBasicParsing "$base/$name" -Method Post -InFile $p|Out-Null}
try{
 $m=(Invoke-WebRequest -UseBasicParsing "$base/m78-continuation-case-archive-tools-v1.json").Content|ConvertFrom-Json;$scripts="$root\M78ContinuationSource\Scripts\ArchiveV1";if(Test-Path $scripts){throw 'Preserve preceding archive tool staging'};New-Item -ItemType Directory $scripts -Force|Out-Null
 $zip="$scripts\tools.zip";Invoke-WebRequest -UseBasicParsing "$base/$($m.archive)" -OutFile $zip;if((Get-FileHash $zip).Hash.ToLower() -ne $m.archiveSHA256){throw 'Archive-tool ZIP SHA mismatch'};Expand-Archive -LiteralPath $zip -DestinationPath $scripts;$tools=@()
 foreach($file in $m.files){$p=Join-Path $scripts $file.path;if((Get-FileHash $p).Hash.ToLower() -ne $file.sha256){throw 'Archive-tool source SHA mismatch'};$tokens=$null;$errors=$null;$ast=[Management.Automation.Language.Parser]::ParseFile($p,[ref]$tokens,[ref]$errors);if($errors.Count){throw 'Archive-tool parser error'};$tools+=@{path=$p;sha256=$file.sha256;parserErrors=@()}}
 $owned="$out\combined-v1";if(Test-Path $owned){throw 'Preserve preceding owned final output'};New-Item -ItemType Directory $owned -Force|Out-Null
 @('FRAMES 120','LOG_EVERY 30','FRAME_SECONDS 0.016666667')|Set-Content "$owned\startup.harness" -Encoding ASCII
 $nav="$root\M78ContinuationNav-combined-v1";if(Test-Path $nav){throw 'Preserve preceding navigation fixture'};$navZip="$owned\navigation-inputs.zip";Invoke-WebRequest -UseBasicParsing "$base/m78-dependent-fixture.zip" -OutFile $navZip
 if((Get-FileHash $navZip).Hash.ToLower() -ne '571d2eeb6d467055d2d00eca46a7b81026e1a226228c336b9bc1f9d73fbbb946'){throw 'Original navigation fixture archive SHA mismatch'};Expand-Archive -LiteralPath $navZip -DestinationPath $nav
 $sdk=@();foreach($name in @('windows-runtime','windows-licenses')){$p="$root\Build\Release\$name";if(!(Test-Path $p -PathType Container)){throw 'Original export SDK directory missing'};$files=@(Get-ChildItem -LiteralPath $p -Recurse -File);$sdk+=@{path=$p;files=$files.Count;bytes=($files|Measure-Object -Property Length -Sum).Sum}}
 $receipt="$out\m78-combined-v1-execution-preparation.json";@{scope='Verified original fixture/tool staging and export SDK presence only; no compilation or test execution';tools=$tools;navigationInputSHA256='571d2eeb6d467055d2d00eca46a7b81026e1a226228c336b9bc1f9d73fbbb946';sdk=$sdk;freeBytes=(Get-PSDrive C).Free}|ConvertTo-Json -Depth 5|Set-Content $receipt -Encoding UTF8;Upload $receipt ([IO.Path]::GetFileName($receipt))
}catch{$p="$out\m78-combined-v1-execution-preparation-error.txt";[string]$_.Exception.Message|Set-Content $p;Upload $p ([IO.Path]::GetFileName($p));exit 1}
